CREATE SEQUENCE public.demo_iban_seq START 10000 MINVALUE 10000 MAXVALUE 99999 NO CYCLE;
ALTER TABLE public.profiles ADD COLUMN iban text DEFAULT lpad(nextval('public.demo_iban_seq')::text,5,'0');
ALTER TABLE public.profiles ADD COLUMN avatar_url text;
UPDATE public.profiles p SET avatar_url=u.raw_user_meta_data->>'avatar_url' FROM auth.users u WHERE u.id=p.id;
CREATE UNIQUE INDEX profiles_iban_unique ON public.profiles(iban);
ALTER TABLE public.profiles ADD CONSTRAINT profiles_iban_format CHECK (iban ~ '^[0-9]{5}$');
COMMENT ON COLUMN public.profiles.tag IS 'DEPRECATED: replaced by five-digit demo iban; internal compatibility only';
COMMENT ON TABLE public.cards IS 'DEPRECATED: Perk is now cardless';
CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.user_roles(user_id,role) SELECT id,'admin'::public.app_role FROM auth.users WHERE lower(email)='danilenkoi271@gmail.com' AND email_confirmed_at IS NOT NULL AND raw_app_meta_data->'providers' ? 'google';
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.assign_perk_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='danilenkoi271@gmail.com' AND NEW.email_confirmed_at IS NOT NULL AND NEW.raw_app_meta_data->'providers' ? 'google' THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER perk_admin_identity AFTER INSERT OR UPDATE OF email,email_confirmed_at,raw_app_meta_data ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_perk_admin();
CREATE TABLE public.trade_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),account_id uuid NOT NULL REFERENCES public.accounts(id),amount numeric(18,2) NOT NULL CHECK(amount>0),multiplier numeric(3,1) NOT NULL CHECK(multiplier BETWEEN 1.1 AND 3),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','success','failed')),payout numeric(18,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),settled_at timestamptz);
GRANT SELECT ON public.trade_orders TO authenticated;
GRANT ALL ON public.trade_orders TO service_role;
ALTER TABLE public.trade_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own orders" ON public.trade_orders FOR SELECT TO authenticated USING(user_id=auth.uid());
ALTER TABLE public.transactions ADD COLUMN order_id uuid REFERENCES public.trade_orders(id);
CREATE UNIQUE INDEX trade_transaction_unique ON public.transactions(order_id,category) WHERE order_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.place_demo_trade(_amount numeric,_multiplier numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.accounts%ROWTYPE; oid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not signed in'; END IF; IF _amount IS NULL OR _amount<=0 OR _amount>=1000000000 OR _amount<>round(_amount,2) THEN RAISE EXCEPTION 'Invalid amount'; END IF; IF _multiplier IS NULL OR _multiplier<1.1 OR _multiplier>3 OR _multiplier<>round(_multiplier,1) THEN RAISE EXCEPTION 'Invalid multiplier'; END IF; SELECT * INTO a FROM public.accounts WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND OR a.balance<_amount THEN RAISE EXCEPTION 'Insufficient funds'; END IF; INSERT INTO public.trade_orders(user_id,account_id,amount,multiplier) VALUES(auth.uid(),a.id,_amount,_multiplier) RETURNING id INTO oid; INSERT INTO public.transactions(account_id,title,category,amount,order_id) VALUES(a.id,'Bot trade · '||_multiplier||'×','investment',-_amount,oid); RETURN oid; END $$;
REVOKE ALL ON FUNCTION public.place_demo_trade(numeric,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.place_demo_trade(numeric,numeric) TO authenticated;
CREATE OR REPLACE FUNCTION public.settle_demo_trade(_id uuid,_success boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.trade_orders%ROWTYPE; result numeric; BEGIN IF _success IS NULL THEN RAISE EXCEPTION 'Choose an outcome'; END IF; SELECT * INTO o FROM public.trade_orders WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF; IF o.status<>'pending' THEN RAISE EXCEPTION 'Order already settled'; END IF; PERFORM 1 FROM public.accounts WHERE id=o.account_id FOR UPDATE; result:=CASE WHEN _success THEN round(o.amount*o.multiplier,2) ELSE 0 END; UPDATE public.trade_orders SET status=CASE WHEN _success THEN 'success' ELSE 'failed' END,payout=result,settled_at=now() WHERE id=o.id; IF _success THEN INSERT INTO public.transactions(account_id,title,category,amount,order_id) VALUES(o.account_id,'Bot trade won · '||o.multiplier||'×','investment_payout',result,o.id); END IF; END $$;
REVOKE ALL ON FUNCTION public.settle_demo_trade(uuid,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.settle_demo_trade(uuid,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.transfer_by_iban(_iban text,_amount numeric,_note text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sender public.accounts%ROWTYPE; recipient public.accounts%ROWTYPE; rid uuid; sid text; tid uuid:=gen_random_uuid(); BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not signed in'; END IF; IF _amount IS NULL OR _amount<=0 OR _amount>=1000000000 OR _amount<>round(_amount,2) THEN RAISE EXCEPTION 'Invalid amount'; END IF; SELECT id INTO rid FROM public.profiles WHERE iban=_iban; IF rid IS NULL THEN RAISE EXCEPTION 'Account not found'; END IF; IF rid=auth.uid() THEN RAISE EXCEPTION 'Cannot transfer to yourself'; END IF; PERFORM id FROM public.accounts WHERE user_id IN (auth.uid(),rid) ORDER BY id FOR UPDATE; SELECT * INTO sender FROM public.accounts WHERE user_id=auth.uid(); SELECT * INTO recipient FROM public.accounts WHERE user_id=rid; IF sender.id IS NULL OR recipient.id IS NULL THEN RAISE EXCEPTION 'Account not found'; END IF; IF sender.balance<_amount THEN RAISE EXCEPTION 'Insufficient funds'; END IF; SELECT iban INTO sid FROM public.profiles WHERE id=auth.uid(); INSERT INTO public.transactions(account_id,title,category,amount,note,transfer_id,counterparty) VALUES(sender.id,'Sent to '||_iban,'transfer',-_amount,_note,tid,_iban),(recipient.id,'Received from '||sid,'transfer',_amount,_note,tid,sid); RETURN tid; END $$;
REVOKE ALL ON FUNCTION public.transfer_by_iban(text,numeric,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.transfer_by_iban(text,numeric,text) TO authenticated;
COMMENT ON FUNCTION public.transfer_by_tag(text,numeric,text) IS 'DEPRECATED: replaced by transfer_by_iban';
REVOKE EXECUTE ON FUNCTION public.transfer_by_tag(text,numeric,text) FROM PUBLIC,anon,authenticated;
COMMENT ON FUNCTION public.lookup_tag(text) IS 'DEPRECATED: replaced by server-side iban lookup';
REVOKE EXECUTE ON FUNCTION public.lookup_tag(text) FROM PUBLIC,anon,authenticated;